  CH.a3_risks = {"kicker": "RISKS", "title": "눈여겨볼 부담과 위험", "sub": "공시(10-Q)와 콜에서 회사가 직접 밝힌 내용", "cols": 2, "items": [{"tag": "현금", "head": "잉여현금흐름 마이너스", "text": "2026년 2·3분기 연속 마이너스. 회사는 투자 사이클 동안 압박이 이어진다고 했습니다.", "warn": 1}, {"tag": "약정", "head": "구매 약정 9,240억 달러", "text": "장비·재고·전력 등 미래 구매 약정과 착수 전 리스 1,520억 달러. 최대치이며 줄 수 있다고 밝혔습니다.", "warn": 1}, {"tag": "부채", "head": "장기부채 1,251억 달러", "text": "1년 전 216억 달러에서 크게 늘었습니다. '26년 3분기 발행 회사채 평균 이자율은 5.55%입니다."}, {"tag": "공급", "head": "연산 부족", "text": "전력·부지·부품 부족으로 수요를 다 못 맞추고, 다른 회사 용량을 빌려 4분기 클라우드 이익률이 낮아질 수 있습니다."}, {"tag": "검색", "head": "AI 모드 수익화", "text": "AI 모드 질의가 빠르게 느는데 광고 수익화는 낮다고 인정했습니다. 2026년 3분기 검색 성장률이 12%로 내려왔습니다."}, {"tag": "법", "head": "반독점 판결", "text": "검색 독점 최종 판결(2025년 12월: 검색 데이터 공유 등)에 항소 중. 광고기술은 매각 대신 행위 제한(2026년 9월). EU 과징금이 이어집니다."}, {"tag": "평가", "head": "지분 평가 변동", "text": "SpaceX 등 보유 지분 가격에 따라 순이익이 수백억 달러씩 오르내립니다. \"한 비상장 회사\"가 앤트로픽이라면 상장 뒤에는 그 지분도 분기마다 주가로 다시 매겨집니다."}, {"tag": "고객", "head": "큰 고객 1곳의 비중", "text": "앤트로픽 S-1의 구글 최소 약정 1,145억 달러는 클라우드 잔고의 약 20%입니다(자체계산). 앤트로픽 상반기 매출은 163억 달러인데 컴퓨팅 약정은 수천억 달러입니다.", "warn": 1}, {"tag": "경쟁", "head": "모델 경쟁", "text": "회사 스스로 코딩 모델은 '개선이 필요하다'고 인정했습니다('26년 2분기). 제미나이 4가 반격입니다."}]}; CH.a3_risks.t = cards;
  CH.a3_known = {"kicker": "KNOWN vs UNKNOWN", "title": "공시와 콜로 알 수 있는 것, 없는 것", "sub": "2026년 10월 31일 기준", "yes": {"title": "알 수 있는 것", "items": ["12분기 매출·이익·현금흐름·설비투자(공시)", "사업별 매출과 클라우드 이익률", "경영진이 밝힌 AI 사용 지표의 흐름", "2026년 주식·채권 조달 규모", "경쟁 3사의 매출·설비투자·클라우드 성장률"]}, "no": {"title": "알 수 없는 것", "items": ["TPU 판매를 뺀 클라우드 성장률과 TPU 마진", "AI 모드 광고 수익화율 숫자", "\"한 비상장 회사\"의 이름(앤트로픽 추정)과 지분 가치", "앤트로픽 약정이 잔고에 들어간 금액", "제미나이 앱 수익(구독·광고) 규모", "2027년 설비투자 금액"]}, "note": "경영진이 밝히는 AI 지표는 분기마다 기준(월 사용자, 분당 토큰 등)이 바뀌어 같은 잣대로 길게 비교하기 어렵습니다."}; CH.a3_known.t = have;
  CH.a3_verdict = {"cols": 3, "kicker": "VERDICT", "title": "총평: 장사는 더 잘하는데, 돈은 미래에 미리 쓰고 있다", "sub": "단위는 칸마다 표시 ('23년 4분기 → '26년 3분기, 회사 공시 기준)", "items": [{"lab": "분기 매출", "big": "+48%", "text": "863억 → 1,276억 달러(자체계산). 13분기 연속 2자릿수 성장"}, {"lab": "영업이익률", "big": "31.8%", "text": "27.5%에서 올랐습니다(자체계산). 투자를 늘리면서도 이익률은 지켰습니다"}, {"lab": "3분기 잉여현금흐름", "big": "-91억 달러", "dk": 1, "text": "설비투자 514억 달러가 영업현금 423억 달러를 넘었습니다"}]}; CH.a3_verdict.t = cards;
  CH.a3_issues = {"cols": 3, "kicker": "PROBLEMS", "title": "위기와 문제점 6가지", "sub": "단위: 억 달러 (회사 공시·콜 기준, 비중은 자체계산)", "items": [{"tag": "1", "head": "현금이 마이너스", "text": "잉여현금흐름이 2분기 −59억, 3분기 −91억 달러. 2027년 설비투자는 더 크게 늘린다고 했습니다.", "warn": 1}, {"tag": "2", "head": "빚과 주식으로 투자", "text": "장기부채 216억 → 1,251억 달러(1년 새). 2026년 회사채 808억·주식 519억 달러 발행, 자사주 매입은 멈췄습니다.", "warn": 1}, {"tag": "3", "head": "약정 9,240억 달러", "text": "미래 구매 약정에 착수 전 리스 1,520억 달러가 따로 있습니다. 수요가 꺾여도 쉽게 줄이기 어려운 돈입니다.", "warn": 1}, {"tag": "4", "head": "큰 고객 쏠림", "text": "앤트로픽 사용 약정 1,145억 달러는 클라우드 잔고의 약 20%(자체계산). 앤트로픽은 구글을 경쟁사로 적었습니다."}, {"tag": "5", "head": "검색 둔화·모델 경쟁", "text": "검색 성장률 2분기 17% → 3분기 12%. AI 모드는 아직 돈을 덜 벌고, 코딩 모델은 열세였다고 회사가 인정했습니다."}, {"tag": "6", "head": "순이익 흔들림·소송", "text": "비상장 지분 평가로 순이익이 2분기 1,122억 → 3분기 265억 달러. 검색 독점 판결은 항소 중입니다."}]}; CH.a3_issues.t = cards;
  CH.a3_why = {"cols": 3, "kicker": "WHY STILL", "title": "그래도 투자할 수 있는 이유 6가지", "sub": "단위: 억 달러 (회사 공시·콜 기준, 계산은 자체계산). 주가·밸류에이션은 따지지 않았습니다", "items": [{"tag": "1", "head": "본업이 아직 빠르다", "text": "3분기 매출 +25%. 검색 질의 증가율은 최근 5년 중 최고라고 회사가 밝혔습니다."}, {"tag": "2", "head": "이익률을 지키는 투자", "text": "영업이익 3년 +71%(237억 → 406억 달러). 돈을 쏟으면서도 이익률이 올랐습니다."}, {"tag": "3", "head": "받을 돈이 쌓여 있다", "text": "클라우드 잔고 5,610억 달러, 55% 남짓이 24개월 안에 매출이 됩니다(약 3,000억 달러, 자체계산)."}, {"tag": "4", "head": "칩·모델·유통을 다 가졌다", "text": "자체 칩 TPU(고객 약 100곳), 제미나이(앱 10억 명), 검색·유튜브·안드로이드라는 판매 통로를 함께 가졌습니다."}, {"tag": "5", "head": "수요를 보고 산다", "text": "TPU 재고는 계약을 맺은 뒤에만 산다고 클라우드 CEO가 말했습니다. 경영진은 자본비용을 웃도는 수익률을 기대했습니다."}, {"tag": "6", "head": "버틸 체력", "text": "현금·유가증권 2,651억 달러. 최근 4분기 영업현금흐름 합계는 1,796억 달러입니다(자체계산)."}], "note": "투자 권유가 아닙니다. 위 이유는 회사가 밝힌 숫자와 말을 정리한 것으로, 약속대로 될지는 앞으로의 분기 실적으로 확인해야 합니다."}; CH.a3_why.t = cards;
