  function ffield(c) {
    var P = function (v) { return (v - c.min) / (c.max - c.min) * 100; };
    var rows = c.items.map(function (it, i) {
      return '<div class="ic__ffr ic__rv" style="--d:' + (i * 0.12) + 's"><div class="ic__ffn"><b>' + it.label + '</b><small>' + it.sub + '</small></div>' +
        '<div class="ic__ffp"><i class="ic__ffx" style="left:' + P(c.price) + '%"></i>' +
        '<div class="ic__ffb" style="left:' + P(it.lo) + '%;--w:' + (P(it.hi) - P(it.lo)) + '%;--d:' + (i * 0.12) + 's"><u>$' + it.lo + '</u><s>$' + it.hi + '</s></div>' +
        (it.mid ? '<em class="ic__ffm" style="left:' + P(it.mid) + '%"><span>$' + it.mid + '</span></em>' : '') + '</div></div>';
    }).join('');
    var ax = '<div class="ic__ffr ic__ffa"><div class="ic__ffn"></div><div class="ic__ffp">' + c.ticks.map(function (t) { return '<span style="left:' + P(t) + '%">$' + t + '</span>'; }).join('') +
      '</div></div>';
    return card(c, pills(c.pills) + '<div class="ic__ff">' + rows + ax + '</div>' + nt(c));
  }
